$chapters = @"

,  {"id":"SAT-10-08-01","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 8: Writing and Language","yearEC":"2024 E.C.","questionText":"Which sentence is correctly punctuated?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"After the concert, we went home."},{"id":"b","text":"After the concert we went home"},{"id":"c","text":"After the concert: we went home."},{"id":"d","text":"After, the concert we went home."}],"correctOptionId":"a","explanation":"A comma after an introductory phrase is correct punctuation.","difficulty":"Easy"},
  {"id":"SAT-10-08-02","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 8: Writing and Language","yearEC":"2024 E.C.","questionText":"Choose the correct form: The students (their/they're/there) homework.","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"their"},{"id":"b","text":"they're"},{"id":"c","text":"there"},{"id":"d","text":"ther"}],"correctOptionId":"a","explanation":"Their is the possessive form needed here.","difficulty":"Easy"},
  {"id":"SAT-10-08-03","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 8: Writing and Language","yearEC":"2024 E.C.","questionText":"Which sentence uses active voice?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"The cat chased the mouse."},{"id":"b","text":"The mouse was chased by the cat."},{"id":"c","text":"The chase happened."},{"id":"d","text":"Chasing occurred."}],"correctOptionId":"a","explanation":"Active voice: subject performs the action. The cat (subject) chased (verb) the mouse.","difficulty":"Easy"},
  {"id":"SAT-10-08-04","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 8: Writing and Language","yearEC":"2024 E.C.","questionText":"Which is a complete sentence?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"Running quickly down the street."},{"id":"b","text":"She ran quickly."},{"id":"c","text":"Quickly."},{"id":"d","text":"Down the street."}],"correctOptionId":"b","explanation":"A complete sentence needs subject and predicate. She (subject) ran quickly (predicate).","difficulty":"Easy"},
  {"id":"SAT-10-08-05","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 8: Writing and Language","yearEC":"2024 E.C.","questionText":"Which word is a transition word?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"however"},{"id":"b","text":"table"},{"id":"c","text":"blue"},{"id":"d","text":"jump"}],"correctOptionId":"a","explanation":"However is a transitional word showing contrast.","difficulty":"Easy"},
  {"id":"SAT-10-08-06","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 8: Writing and Language","yearEC":"2024 E.C.","questionText":"Correct the comma splice: It rained, we stayed inside.","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"It rained; we stayed inside."},{"id":"b","text":"It rained we stayed inside."},{"id":"c","text":"It, rained we stayed inside."},{"id":"d","text":"It rained, stayed inside."}],"correctOptionId":"a","explanation":"A semicolon correctly joins two related independent clauses.","difficulty":"Easy"},
  {"id":"SAT-10-08-07","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 8: Writing and Language","yearEC":"2024 E.C.","questionText":"Which is the correct possessive form?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"the dog's bone"},{"id":"b","text":"the dogs bone"},{"id":"c","text":"the dogs' bone"},{"id":"d","text":"the dog bone"}],"correctOptionId":"a","explanation":"One dog = dog's (singular possessive).","difficulty":"Easy"},
  {"id":"SAT-10-08-08","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 8: Writing and Language","yearEC":"2024 E.C.","questionText":"Which sentence has correct subject-verb agreement?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"The team wins often."},{"id":"b","text":"The team win often."},{"id":"c","text":"The teams wins often."},{"id":"d","text":"The team winning often."}],"correctOptionId":"a","explanation":"Team is singular, so it takes wins (not win).","difficulty":"Easy"},
  {"id":"SAT-10-08-09","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 8: Writing and Language","yearEC":"2024 E.C.","questionText":"Which sentence uses a semicolon correctly?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"I like cats; she likes dogs."},{"id":"b","text":"I like; cats she likes dogs."},{"id":"c","text":"I like cats she; likes dogs."},{"id":"d","text":"I; like cats she likes dogs."}],"correctOptionId":"a","explanation":"Semicolons join two related independent clauses without a conjunction.","difficulty":"Easy"},
  {"id":"SAT-10-08-10","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 8: Writing and Language","yearEC":"2024 E.C.","questionText":"Which is an example of parallel structure?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"She likes reading, writing, and drawing."},{"id":"b","text":"She likes to read, writing, and draw."},{"id":"c","text":"She likes reading, to write, and draw."},{"id":"d","text":"She likes read, writing, and to draw."}],"correctOptionId":"a","explanation":"Parallel structure uses the same grammatical form for items in a list.","difficulty":"Easy"},
  {"id":"SAT-10-08-11","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 8: Writing and Language","yearEC":"2024 E.C.","questionText":"Which revision improves clarity? Original: Due to the fact that it was raining.","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"Because it was raining."},{"id":"b","text":"In the event that it was raining."},{"id":"c","text":"At this point in time it was raining."},{"id":"d","text":"On account of the fact it was raining."}],"correctOptionId":"a","explanation":"Because is concise and clear, replacing wordy phrases.","difficulty":"Medium"},
  {"id":"SAT-10-08-12","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 8: Writing and Language","yearEC":"2024 E.C.","questionText":"Which sentence contains a misplaced modifier?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"Running quickly, the bus was caught."},{"id":"b","text":"Running quickly, she caught the bus."},{"id":"c","text":"She caught the bus running quickly."},{"id":"d","text":"The running bus was caught quickly."}],"correctOptionId":"a","explanation":"The bus cannot run quickly. The modifier should be near the subject performing the action.","difficulty":"Medium"},
  {"id":"SAT-10-08-13","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 8: Writing and Language","yearEC":"2024 E.C.","questionText":"Which word choice is most formal?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"investigate"},{"id":"b","text":"check out"},{"id":"c","text":"look into"},{"id":"d","text":"snoop around"}],"correctOptionId":"a","explanation":"Investigate is the most formal and precise word choice.","difficulty":"Medium"},
  {"id":"SAT-10-08-14","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 8: Writing and Language","yearEC":"2024 E.C.","questionText":"Which transition shows contrast?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"nevertheless"},{"id":"b","text":"therefore"},{"id":"c","text":"moreover"},{"id":"d","text":"similarly"}],"correctOptionId":"a","explanation":"Nevertheless signals contrast or concession.","difficulty":"Medium"},
  {"id":"SAT-10-08-15","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 8: Writing and Language","yearEC":"2024 E.C.","questionText":"Correct the error: Each of the students have a book.","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"Each of the students has a book."},{"id":"b","text":"Each of the students have books."},{"id":"c","text":"Each of the student has a book."},{"id":"d","text":"Each of the students having a book."}],"correctOptionId":"a","explanation":"Each is singular and takes has (not have).","difficulty":"Medium"},
  {"id":"SAT-10-08-16","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 8: Writing and Language","yearEC":"2024 E.C.","questionText":"Which sentence is most concise?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"The reason is because he was late."},{"id":"b","text":"He was late."},{"id":"c","text":"The reason why he was late is because..."},{"id":"d","text":"Because of the reason he was late."}],"correctOptionId":"b","explanation":"He was late is the most concise way to express this idea.","difficulty":"Medium"},
  {"id":"SAT-10-08-17","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 8: Writing and Language","yearEC":"2024 E.C.","questionText":"Which sentence correctly uses a colon?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"I need: eggs, milk, and bread."},{"id":"b","text":"I need eggs, milk, and bread:"},{"id":"c","text":"I need eggs: milk, and bread."},{"id":"d","text":"I need eggs, milk: and bread."}],"correctOptionId":"b","explanation":"A colon introduces a list and comes after a complete sentence.","difficulty":"Medium"},
  {"id":"SAT-10-08-18","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 8: Writing and Language","yearEC":"2024 E.C.","questionText":"Which sentence has correct pronoun-antecedent agreement?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"Everyone brought their book."},{"id":"b","text":"Everyone brought his or her book."},{"id":"c","text":"Everyone brought his book."},{"id":"d","text":"Everyone brought them book."}],"correctOptionId":"b","explanation":"Everyone is singular, so his or her is the most precise agreement.","difficulty":"Medium"},
  {"id":"SAT-10-08-19","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 8: Writing and Language","yearEC":"2024 E.C.","questionText":"Which is an example of a complex sentence?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"Although it rained, we went out."},{"id":"b","text":"It rained."},{"id":"c","text":"We went out."},{"id":"d","text":"It rained; we went out."}],"correctOptionId":"a","explanation":"A complex sentence has an independent clause and a dependent clause.","difficulty":"Medium"},
  {"id":"SAT-10-08-20","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 8: Writing and Language","yearEC":"2024 E.C.","questionText":"Which revision eliminates wordiness? Original: At this point in time, we are currently working on.","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"We are working on."},{"id":"b","text":"At this point in time we are working on."},{"id":"c","text":"We are currently, at this point, working on."},{"id":"d","text":"Currently at this time we are working on."}],"correctOptionId":"a","explanation":"We are working on eliminates redundant time expressions.","difficulty":"Medium"},
  {"id":"SAT-10-08-21","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 8: Writing and Language","yearEC":"2024 E.C.","questionText":"Which sentence contains a dangling modifier?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"After studying hard, the test was easy."},{"id":"b","text":"After studying hard, she found the test easy."},{"id":"c","text":"She studied hard, and the test was easy."},{"id":"d","text":"The test was easy after she studied hard."}],"correctOptionId":"a","explanation":"The test cannot study hard. The modifier must be near the subject who studied.","difficulty":"Hard"},
  {"id":"SAT-10-08-22","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 8: Writing and Language","yearEC":"2024 E.C.","questionText":"Which sentence uses the subjunctive mood correctly?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"If I were you, I would go."},{"id":"b","text":"If I was you, I would go."},{"id":"c","text":"If I am you, I would go."},{"id":"d","text":"If I be you, I would go."}],"correctOptionId":"a","explanation":"The subjunctive mood uses were (not was) for hypothetical situations.","difficulty":"Hard"},
  {"id":"SAT-10-08-23","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 8: Writing and Language","yearEC":"2024 E.C.","questionText":"Which sentence correctly uses an apostrophe?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"The children's toys were scattered."},{"id":"b","text":"The childrens' toys were scattered."},{"id":"c","text":"The childrens toys were scattered."},{"id":"d","text":"The children' toys were scattered."}],"correctOptionId":"a","explanation":"Children is an irregular plural, so the possessive is children's.","difficulty":"Hard"},
  {"id":"SAT-10-08-24","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 8: Writing and Language","yearEC":"2024 E.C.","questionText":"Which revision improves sentence variety?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"Mix simple and complex sentences"},{"id":"b","text":"Use only short sentences"},{"id":"c","text":"Use only long sentences"},{"id":"d","text":"Avoid all transitions"}],"correctOptionId":"a","explanation":"Sentence variety improves readability and engagement.","difficulty":"Hard"},
  {"id":"SAT-10-08-25","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 8: Writing and Language","yearEC":"2024 E.C.","questionText":"Which sentence is grammatically correct?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"Neither the teacher nor the students were present."},{"id":"b","text":"Neither the teacher nor the students was present."},{"id":"c","text":"Neither the teacher nor the students is present."},{"id":"d","text":"Neither the teacher nor the students be present."}],"correctOptionId":"a","explanation":"With neither/nor, the verb agrees with the nearer subject (students, plural).","difficulty":"Hard"},
  {"id":"SAT-10-08-26","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 8: Writing and Language","yearEC":"2024 E.C.","questionText":"Which is an example of an em dash used correctly?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"The results were surprising---and revealing."},{"id":"b","text":"The results were surprising---and---revealing."},{"id":"c","text":"The---results were surprising and revealing."},{"id":"d","text":"The results were surprising and revealing---"}],"correctOptionId":"a","explanation":"An em dash can replace a comma or colon for emphasis.","difficulty":"Hard"},
  {"id":"SAT-10-08-27","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 8: Writing and Language","yearEC":"2024 E.C.","questionText":"Which sentence demonstrates effective parallel structure in a complex list?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"The program aims to educate, to inspire, and to empower."},{"id":"b","text":"The program aims to educate, inspiring, and empowerment."},{"id":"c","text":"The program aims educating, inspiring, and empowering."},{"id":"d","text":"The program aims to educate, to inspire, and empowerment."}],"correctOptionId":"a","explanation":"All items use the infinitive form for perfect parallelism.","difficulty":"Hard"},
  {"id":"SAT-10-08-28","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 8: Writing and Language","yearEC":"2024 E.C.","questionText":"Which sentence correctly uses a semicolon and conjunctive adverb?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"It was late; however, we stayed."},{"id":"b","text":"It was late, however, we stayed."},{"id":"c","text":"It was late however; we stayed."},{"id":"d","text":"It was; late however we stayed."}],"correctOptionId":"a","explanation":"Semicolon before conjunctive adverb, comma after: ; however,","difficulty":"Hard"},
  {"id":"SAT-10-08-29","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 8: Writing and Language","yearEC":"2024 E.C.","questionText":"Which word choice is most precise?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"devoured"},{"id":"b","text":"ate"},{"id":"c","text":"consumed"},{"id":"d","text":"had"}],"correctOptionId":"a","explanation":"Devoured is the most vivid and precise verb choice.","difficulty":"Hard"},
  {"id":"SAT-10-08-30","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 8: Writing and Language","yearEC":"2024 E.C.","questionText":"Which revision most effectively combines sentences?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"Combine related ideas with subordination"},{"id":"b","text":"Make all sentences the same length"},{"id":"c","text":"Remove all conjunctions"},{"id":"d","text":"Use only compound sentences"}],"correctOptionId":"a","explanation":"Subordination shows relationships between ideas and improves flow.","difficulty":"Hard"},
  {"id":"SAT-10-09-01","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 9: Essay Writing","yearEC":"2024 E.C.","questionText":"A strong thesis statement should:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"take a clear position"},{"id":"b","text":"be a question"},{"id":"c","text":"be a fact"},{"id":"d","text":"be vague"}],"correctOptionId":"a","explanation":"A thesis must clearly state the writer's position on the topic.","difficulty":"Easy"},
  {"id":"SAT-10-09-02","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 9: Essay Writing","yearEC":"2024 E.C.","questionText":"The introduction paragraph should:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"hook, background, thesis"},{"id":"b","text":"only thesis"},{"id":"c","text":"only conclusion"},{"id":"d","text":"only evidence"}],"correctOptionId":"a","explanation":"Introductions typically include a hook, background information, and a thesis statement.","difficulty":"Easy"},
  {"id":"SAT-10-09-03","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 9: Essay Writing","yearEC":"2024 E.C.","questionText":"What is the purpose of a topic sentence?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"state the paragraph's main idea"},{"id":"b","text":"conclude the essay"},{"id":"c","text":"provide evidence"},{"id":"d","text":"introduce the author"}],"correctOptionId":"a","explanation":"A topic sentence introduces the main idea of a body paragraph.","difficulty":"Easy"},
  {"id":"SAT-10-09-04","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 9: Essay Writing","yearEC":"2024 E.C.","questionText":"Which is a proper essay structure?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"introduction, body, conclusion"},{"id":"b","text":"body, conclusion"},{"id":"c","text":"conclusion only"},{"id":"d","text":"introduction only"}],"correctOptionId":"a","explanation":"Standard essay structure: introduction, body paragraphs, conclusion.","difficulty":"Easy"},
  {"id":"SAT-10-09-05","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 9: Essay Writing","yearEC":"2024 E.C.","questionText":"Evidence in an essay should:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"support the claim"},{"id":"b","text":"contradict the claim"},{"id":"c","text":"be unrelated"},{"id":"d","text":"replace analysis"}],"correctOptionId":"a","explanation":"Evidence must directly support and strengthen the writer's claims.","difficulty":"Easy"},
  {"id":"SAT-10-09-06","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 9: Essay Writing","yearEC":"2024 E.C.","questionText":"A conclusion should:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"restate thesis and summarize"},{"id":"b","text":"introduce new ideas"},{"id":"c","text":"contradict body"},{"id":"d","text":"be longer than introduction"}],"correctOptionId":"a","explanation":"Conclusions restate the thesis and summarize key points.","difficulty":"Easy"},
  {"id":"SAT-10-09-07","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 9: Essay Writing","yearEC":"2024 E.C.","questionText":"Transition words help:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"connect ideas"},{"id":"b","text":"confuse readers"},{"id":"c","text":"fill space"},{"id":"d","text":"hide weak points"}],"correctOptionId":"a","explanation":"Transitions show relationships between ideas and improve coherence.","difficulty":"Easy"},
  {"id":"SAT-10-09-08","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 9: Essay Writing","yearEC":"2024 E.C.","questionText":"What makes a good hook?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"attention-grabbing opening"},{"id":"b","text":"boring statement"},{"id":"c","text":"definition only"},{"id":"d","text":"conclusion"}],"correctOptionId":"a","explanation":"A hook engages the reader from the first sentence.","difficulty":"Easy"},
  {"id":"SAT-10-09-09","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 9: Essay Writing","yearEC":"2024 E.C.","questionText":"Which is a strong thesis?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"Schools should teach financial literacy because..."},{"id":"b","text":"Financial literacy is taught."},{"id":"c","text":"Should schools teach?"},{"id":"d","text":"This is about money."}],"correctOptionId":"a","explanation":"A strong thesis takes a clear, arguable position with reasoning.","difficulty":"Easy"},
  {"id":"SAT-10-09-10","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 9: Essay Writing","yearEC":"2024 E.C.","questionText":"Body paragraphs should contain:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"topic sentence, evidence, analysis"},{"id":"b","text":"only opinions"},{"id":"c","text":"only facts"},{"id":"d","text":"only transitions"}],"correctOptionId":"a","explanation":"Effective body paragraphs include a topic sentence, supporting evidence, and analysis.","difficulty":"Easy"},
  {"id":"SAT-10-09-11","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 9: Essay Writing","yearEC":"2024 E.C.","questionText":"Analysis in an essay means:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"explaining why evidence matters"},{"id":"b","text":"listing facts"},{"id":"c","text":"summarizing sources"},{"id":"d","text":"quoting experts"}],"correctOptionId":"a","explanation":"Analysis explains the significance and relevance of evidence to the claim.","difficulty":"Medium"},
  {"id":"SAT-10-09-12","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 9: Essay Writing","yearEC":"2024 E.C.","questionText":"Which word choice is most appropriate for academic writing?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"demonstrate"},{"id":"b","text":"show"},{"id":"c","text":"prove"},{"id":"d","text":"make clear"}],"correctOptionId":"a","explanation":"Demonstrate is precise and formal, appropriate for academic writing.","difficulty":"Medium"},
  {"id":"SAT-10-09-13","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 9: Essay Writing","yearEC":"2024 E.C.","questionText":"A counterargument should be:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"addressed and refuted"},{"id":"b","text":"ignored"},{"id":"c","text":"accepted"},{"id":"d","text":"hidden"}],"correctOptionId":"a","explanation":"Addressing and refuting counterarguments strengthens the writer's position.","difficulty":"Medium"},
  {"id":"SAT-10-09-14","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 9: Essay Writing","yearEC":"2024 E.C.","questionText":"Which is an effective introduction strategy?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"start with a relevant quote"},{"id":"b","text":"start with a dictionary"},{"id":"c","text":"start with a question only"},{"id":"d","text":"start with conclusion"}],"correctOptionId":"a","explanation":"A relevant quote can effectively engage readers and introduce the topic.","difficulty":"Medium"},
  {"id":"SAT-10-09-15","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 9: Essay Writing","yearEC":"2024 E.C.","questionText":"Which transition shows cause and effect?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"therefore"},{"id":"b","text":"however"},{"id":"c","text":"furthermore"},{"id":"d","text":"in addition"}],"correctOptionId":"a","explanation":"Therefore indicates a cause-and-effect relationship.","difficulty":"Medium"},
  {"id":"SAT-10-09-16","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 9: Essay Writing","yearEC":"2024 E.C.","questionText":"The most effective essays:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"focus on one main idea"},{"id":"b","text":"cover many topics"},{"id":"c","text":"avoid evidence"},{"id":"d","text":"use only one paragraph"}],"correctOptionId":"a","explanation":"Effective essays maintain focus on a single, well-developed main idea.","difficulty":"Medium"},
  {"id":"SAT-10-09-17","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 9: Essay Writing","yearEC":"2024 E.C.","questionText":"Which is a proper way to integrate a quote?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"introduce, cite, explain"},{"id":"b","text":"drop in without context"},{"id":"c","text":"quote entire paragraph"},{"id":"d","text":"paraphrase only"}],"correctOptionId":"a","explanation":"Effective quote integration: introduce the source, provide the quote, then explain its relevance.","difficulty":"Medium"},
  {"id":"SAT-10-09-18","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 9: Essay Writing","yearEC":"2024 E.C.","questionText":"A weak thesis:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"states a fact"},{"id":"b","text":"takes a position"},{"id":"c","text":"is arguable"},{"id":"d","text":"has reasons"}],"correctOptionId":"a","explanation":"A fact cannot be argued. A thesis must be arguable and take a position.","difficulty":"Medium"},
  {"id":"SAT-10-09-19","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 9: Essay Writing","yearEC":"2024 E.C.","questionText":"Which sentence is most effective in an essay conclusion?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"In conclusion, this essay has shown that..."},{"id":"b","text":"This is the end."},{"id":"c","text":"I am done writing."},{"id":"d","text":"Goodbye."}],"correctOptionId":"a","explanation":"A conclusion effectively restates the thesis and summarizes the argument.","difficulty":"Medium"},
  {"id":"SAT-10-09-20","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 9: Essay Writing","yearEC":"2024 E.C.","questionText":"Effective paragraphs are:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"unified and coherent"},{"id":"b","text":"disorganized"},{"id":"c","text":"full of errors"},{"id":"d","text":"one sentence long"}],"correctOptionId":"a","explanation":"Unified paragraphs focus on one idea; coherent paragraphs flow logically.","difficulty":"Medium"},
  {"id":"SAT-10-09-21","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 9: Essay Writing","yearEC":"2024 E.C.","questionText":"Which is the strongest evidence?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"peer-reviewed study"},{"id":"b","text":"personal opinion"},{"id":"c","text":"random blog"},{"id":"d","text":"unverified claim"}],"correctOptionId":"a","explanation":"Peer-reviewed studies provide the most credible evidence.","difficulty":"Hard"},
  {"id":"SAT-10-09-22","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 9: Essay Writing","yearEC":"2024 E.C.","questionText":"A sophisticated essay:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"acknowledges complexity"},{"id":"b","text":"oversimplifies"},{"id":"c","text":"avoids nuance"},{"id":"d","text":"ignores counterarguments"}],"correctOptionId":"a","explanation":"Sophisticated writing acknowledges complexity and multiple perspectives.","difficulty":"Hard"},
  {"id":"SAT-10-09-23","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 9: Essay Writing","yearEC":"2024 E.C.","questionText":"Which revision strengthens this sentence: 'Things are getting worse.'?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"Specific evidence needed"},{"id":"b","text":"Keep as is"},{"id":"c","text":"Make longer"},{"id":"d","text":"Add more things"}],"correctOptionId":"a","explanation":"Vague claims need specific evidence to be persuasive.","difficulty":"Hard"},
  {"id":"SAT-10-09-24","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 9: Essay Writing","yearEC":"2024 E.C.","questionText":"Effective counterargument includes:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"fair representation then refutation"},{"id":"b","text":"misrepresentation"},{"id":"c","text":"ignoring it"},{"id":"d","text":"accepting it"}],"correctOptionId":"a","explanation":"Fair representation of opposing views followed by evidence-based refutation is most effective.","difficulty":"Hard"},
